function Expand-EmbeddedBootstrap {
    if (Test-Path -LiteralPath $SourceScript -PathType Leaf) {
        Remove-Item -LiteralPath $SourceScript -Force -ErrorAction SilentlyContinue
    }
    try {
        $compressed = [Convert]::FromBase64String(($EmbeddedBootstrapGzipBase64 -replace '\s', ''))
        $input = New-Object System.IO.MemoryStream(, $compressed)
        try {
            $gzip = New-Object System.IO.Compression.GZipStream(
                $input,
                [System.IO.Compression.CompressionMode]::Decompress
            )
            try {
                $output = New-Object System.IO.MemoryStream
                try {
                    $gzip.CopyTo($output)
                    [System.IO.File]::WriteAllBytes($SourceScript, $output.ToArray())
                }
                finally {
                    $output.Dispose()
                }
            }
            finally {
                $gzip.Dispose()
            }
        }
        finally {
            $input.Dispose()
        }
    }
    catch {
        throw "Vestavěný Python bootstrap se nepodařilo rozbalit: $($_.Exception.Message)"
    }
    $actual = (Get-FileHash -LiteralPath $SourceScript -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $EmbeddedBootstrapSha256) {
        Remove-Item -LiteralPath $SourceScript -Force -ErrorAction SilentlyContinue
        throw "SHA-256 vestavěného Python bootstrapu nesouhlasí. Očekáváno $EmbeddedBootstrapSha256, zjištěno $actual."
    }
}

function Remove-EmbeddedBootstrap {
    Remove-Item -LiteralPath $SourceScript -Force -ErrorAction SilentlyContinue
}

# Integrovaná migrace MATLAB figure bridge. Instalační skript neopírá opravu o
# samostatný hotfix: před každým Install/Resume opraví případnou starší lokální
# kopii bootstrapu a následně ověří, že MATLAB kód neobsahuje identifikátory
# začínající podtržítkem.
$LegacyMatlabBridgeIdentifiers = [ordered]@{
    "__emcp_after_figs__"       = "emcpBridgeAfterFigs"
    "__emcp_before_figs__"      = "emcpBridgeBeforeFigs"
    "__emcp_new_mask__"         = "emcpBridgeNewMask"
    "__emcp_probe_index__"      = "emcpBridgeProbeIndex"
    "__emcp_figs__"             = "emcpBridgeFigs"
    "__emcp_numbers__"          = "emcpBridgeNumbers"
    "__emcp_order__"            = "emcpBridgeOrder"
    "__emcp_count__"            = "emcpBridgeCount"
    "__emcp_index__"            = "emcpBridgeIndex"
    "__emcp_file__"             = "emcpBridgeFile"
    "__emcp_capture_error__"     = "emcpBridgeCaptureError"
    "__emcp_capture_message__"   = "emcpBridgeCaptureMessage"
}

function Assert-MatlabFigureBridgeSource {
    param([Parameter(Mandatory = $true)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Engineering MCP bootstrap nebyl nalezen: $Path"
    }
    $text = [System.IO.File]::ReadAllText($Path)
    $invalidPattern = '(?m)^\s*(?:(?:for|catch)\s+)?(__emcp_[A-Za-z0-9_]*__)\b'
    $matches = [System.Text.RegularExpressions.Regex]::Matches($text, $invalidPattern)
    if ($matches.Count -gt 0) {
        $names = @($matches | ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique)
        throw ("MATLAB figure bridge stále obsahuje neplatné identifikátory: " + ($names -join ", "))
    }
}

