        'OPENAPI_VERIFICATION_REPORT' = "samostatný detailní report OpenAPI kontroly"
        '--mcp-stdio-probe' = "přímý stdio preflight před OpenAPI"
    }
    $missing = @()
    foreach ($entry in $requiredMarkers.GetEnumerator()) {
        if (-not $text.Contains([string]$entry.Key)) {
            $missing += [string]$entry.Value
        }
    }
    if ($missing.Count -gt 0) {
        throw (
            "Vestavěný jednotný bootstrap 2.9.18 je neúplný nebo interně nekonzistentní. Detail: " +
            ($missing -join ", ") + ". Ověřte SHA-256 instalačního souboru."
        )
    }
}


function Repair-MatlabFigureBridgeSource {
    param([Parameter(Mandatory = $true)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return $false
    }

    $text = [System.IO.File]::ReadAllText($Path)
    $original = $text
    foreach ($entry in $LegacyMatlabBridgeIdentifiers.GetEnumerator()) {
        $text = $text.Replace([string]$entry.Key, [string]$entry.Value)
    }
    # Upgrade only the immediately preceding known releases. Other custom version
    # strings are left untouched.
    $text = $text.Replace('BOOTSTRAPPER_VERSION = "2.6.2"', 'BOOTSTRAPPER_VERSION = "2.9.18"')
    $text = $text.Replace('BOOTSTRAPPER_VERSION = "2.6.3"', 'BOOTSTRAPPER_VERSION = "2.9.18"')
    $text = $text.Replace('BOOTSTRAPPER_VERSION = "2.6.4"', 'BOOTSTRAPPER_VERSION = "2.9.18"')

    if (-not [string]::Equals($text, $original, [System.StringComparison]::Ordinal)) {
        [System.IO.File]::WriteAllText($Path, $text, $Utf8NoBom)
        Write-Host "[*] Integrovaná oprava MATLAB figure bridge byla použita: $Path"
    }

    Assert-MatlabFigureBridgeSource -Path $Path
    return (-not [string]::Equals($text, $original, [System.StringComparison]::Ordinal))
}

function Show-Usage {
    Write-Host "Použití:"
    Write-Host "  .\install-engineering-mcp-unified-v2.9.18.ps1 [-Install|-Resume] [volby]"
    Write-Host "  .\install-engineering-mcp-unified-v2.9.18.ps1 -Uninstall"
    Write-Host ""
    Write-Host "Jednotný instalátor spravuje ANSYS, MATLAB, WeKnora a PhysicsNeMo v jednom stavu,"
    Write-Host "jedné plánované úloze a jednom MCPO/OpenAPI gateway na portu 8200."
    Write-Host ""
    Write-Host "PhysicsNeMo:"
    Write-Host "  -NoPhysNeMo                              vypne automatickou instalaci/detekci"
    Write-Host "  -PhysNeMoDistro Ubuntu                   WSL2 distribuce"
    Write-Host "  -PhysNeMoInstallDir /home/...            spravovaný adresář ve WSL2"
    Write-Host "  -PhysNeMoNatPort 9911                    interní loopback MCP port"
    Write-Host "  -NeMoAgentToolkitVersion 1.9.0           připnutá verze NAT"
    Write-Host "  -PhysicsNeMoVersion 2.2.2                připnutá verze PhysicsNeMo"
    Write-Host "  -PhysicsNeMoProfile base|cu12|cu13       profil závislostí"
    Write-Host "  -PhysicsNeMoSourceRef v2.2.2             auditovaný Git ref"
    Write-Host "  -NoPhysNeMoPrerequisiteInstall           neinstaluje chybějící WSL prerequisites"
    Write-Host "  -PhysNeMoAgentBaseUrl URL                OpenAI kompatibilní endpoint NAT agenta"
    Write-Host "  -PhysNeMoAgentModel MODEL                model interního NAT agenta"
    Write-Host "  -PhysNeMoAgentApiKeyFile SOUBOR          provider API klíč; neukládá se do příkazové řádky"
    Write-Host "  -NoPhysNeMoAgentAutoDetect               vypne detekci e-INFRA Open WebUI runtime.json"
    Write-Host "  Bez LLM údajů se PhysicsNeMo nainstaluje; physnemo__solve vrátí configuration_required."
    Write-Host "  -PhysNeMoOpenWebUIUrl URL                backend Open WebUI pro čtení file-id"
    Write-Host "  -PhysNeMoOpenWebUIApiKeyFile SOUBOR      Open WebUI API klíč pro LLM agenta i file-id bridge"
    Write-Host "  -PhysNeMoArtifactBaseUrl URL              veřejná základní URL podepsaných artifactů"
    Write-Host "  -OpenWebUIDatabase CESTA                 explicitní cesta k nativní webui.db (jinak auto-detekce)"
    Write-Host "  -NoOpenWebUINativeSync                   nevytváří spravovaný API klíč ani živě nenačítá tool servery"
    Write-Host "  -NoOpenWebUIDlpRepair                    neaktivuje existující požadovaný globální DLP filtr"
    Write-Host "  -AllowPhysNeMoWithoutAgent               povolí diagnostickou instalaci bez funkčního solve agenta"
    Write-Host ""
    Write-Host "WeKnora: -WeKnoraUrl, -WeKnoraApiUrl, -WeKnoraApiKeyFile,"
    Write-Host "          -WeKnoraTenantId|-WeKnoraTenantName, -WeKnoraCaCertificate"
    Write-Host "MATLAB:  -MatlabImageTest, -NoMatlabRepair, -ForceCloseMatlab"
    Write-Host "Obecně:  -Community|-NoCommunity, -NoStart, -NoAutostart, -Port, -StartupTimeout, -Force"
    Write-Host ""
    Write-Host "Bez explicitního režimu se bezpečně použije -Resume."
    Write-Host "Engineering MCP podporuje HTTP i HTTPS WeKnora; vzdálené HTTP není šifrované."
}


# Ruční dispatch je záměrný. Vylučuje nejasnosti PowerShell parameter sets a
# zaručuje, že režim UNINSTALL nemůže propadnout do instalační větve.
$SelectedModes = @()
if ($Install.IsPresent) { $SelectedModes += "INSTALL" }
if ($Resume.IsPresent) { $SelectedModes += "RESUME" }
if ($Uninstall.IsPresent) { $SelectedModes += "UNINSTALL" }

if ($SelectedModes.Count -eq 0) {
    $Mode = "RESUME"
    $Resume = [switch]$true
    Write-Host "[*] Režim nebyl zadán; používám bezpečný -Resume."
}
elseif ($SelectedModes.Count -eq 1) {
    $Mode = $SelectedModes[0]
}
else {
    Write-Host "[!] Zvolte nejvýše jeden režim: -Install, -Resume nebo -Uninstall." -ForegroundColor Red
    Show-Usage
    exit 64
}

if ($Mode -eq "UNINSTALL") {
    $InvalidUninstallOptions = @()
    if ($Community.IsPresent) { $InvalidUninstallOptions += "-Community" }
    if ($NoCommunity.IsPresent) { $InvalidUninstallOptions += "-NoCommunity" }
    if ($NoStart.IsPresent) { $InvalidUninstallOptions += "-NoStart" }
    if ($NoAutostart.IsPresent) { $InvalidUninstallOptions += "-NoAutostart" }
    if ($Force.IsPresent) { $InvalidUninstallOptions += "-Force" }
    if ($MatlabImageTest.IsPresent) { $InvalidUninstallOptions += "-MatlabImageTest" }
    if ($NoMatlabRepair.IsPresent) { $InvalidUninstallOptions += "-NoMatlabRepair" }
    if ($ForceCloseMatlab.IsPresent) { $InvalidUninstallOptions += "-ForceCloseMatlab" }
    if ($null -ne $MatlabHealthTimeout) { $InvalidUninstallOptions += "-MatlabHealthTimeout" }
    if ($NoPhysNeMo.IsPresent) { $InvalidUninstallOptions += "-NoPhysNeMo" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoDistro)) { $InvalidUninstallOptions += "-PhysNeMoDistro" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoInstallDir)) { $InvalidUninstallOptions += "-PhysNeMoInstallDir" }
    if ($null -ne $PhysNeMoNatPort) { $InvalidUninstallOptions += "-PhysNeMoNatPort" }
    if (-not [string]::IsNullOrWhiteSpace($NeMoAgentToolkitVersion)) { $InvalidUninstallOptions += "-NeMoAgentToolkitVersion" }
    if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoVersion)) { $InvalidUninstallOptions += "-PhysicsNeMoVersion" }
    if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoProfile)) { $InvalidUninstallOptions += "-PhysicsNeMoProfile" }
    if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoSourceRef)) { $InvalidUninstallOptions += "-PhysicsNeMoSourceRef" }
    if ($NoPhysNeMoPrerequisiteInstall.IsPresent) { $InvalidUninstallOptions += "-NoPhysNeMoPrerequisiteInstall" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentBaseUrl)) { $InvalidUninstallOptions += "-PhysNeMoAgentBaseUrl" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentModel)) { $InvalidUninstallOptions += "-PhysNeMoAgentModel" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentApiKeyFile)) { $InvalidUninstallOptions += "-PhysNeMoAgentApiKeyFile" }
    if ($NoPhysNeMoAgentAutoDetect.IsPresent) { $InvalidUninstallOptions += "-NoPhysNeMoAgentAutoDetect" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoOpenWebUIUrl)) { $InvalidUninstallOptions += "-PhysNeMoOpenWebUIUrl" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoOpenWebUIApiKeyFile)) { $InvalidUninstallOptions += "-PhysNeMoOpenWebUIApiKeyFile" }
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoArtifactBaseUrl)) { $InvalidUninstallOptions += "-PhysNeMoArtifactBaseUrl" }
    if (-not [string]::IsNullOrWhiteSpace($OpenWebUIDatabase)) { $InvalidUninstallOptions += "-OpenWebUIDatabase" }
    if ($NoOpenWebUINativeSync.IsPresent) { $InvalidUninstallOptions += "-NoOpenWebUINativeSync" }
    if ($NoOpenWebUIDlpRepair.IsPresent) { $InvalidUninstallOptions += "-NoOpenWebUIDlpRepair" }
    if ($AllowPhysNeMoWithoutAgent.IsPresent) { $InvalidUninstallOptions += "-AllowPhysNeMoWithoutAgent" }
    if ($NoWeKnora.IsPresent) { $InvalidUninstallOptions += "-NoWeKnora" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraUrl)) { $InvalidUninstallOptions += "-WeKnoraUrl" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiUrl)) { $InvalidUninstallOptions += "-WeKnoraApiUrl" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiKeyFile)) { $InvalidUninstallOptions += "-WeKnoraApiKeyFile" }
    if ($null -ne $WeKnoraTenantId) { $InvalidUninstallOptions += "-WeKnoraTenantId" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraTenantName)) { $InvalidUninstallOptions += "-WeKnoraTenantName" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraCaCertificate)) { $InvalidUninstallOptions += "-WeKnoraCaCertificate" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraDistro)) { $InvalidUninstallOptions += "-WeKnoraDistro" }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraInstallDir)) { $InvalidUninstallOptions += "-WeKnoraInstallDir" }
    if ($NoWeKnoraAutoProvision.IsPresent) { $InvalidUninstallOptions += "-NoWeKnoraAutoProvision" }
    if ($WeKnoraAllowEmptyCatalog.IsPresent) { $InvalidUninstallOptions += "-WeKnoraAllowEmptyCatalog" }
    if ($null -ne $WeKnoraHealthTimeout) { $InvalidUninstallOptions += "-WeKnoraHealthTimeout" }
    if ($null -ne $Port) { $InvalidUninstallOptions += "-Port" }
    if ($null -ne $StartupTimeout) { $InvalidUninstallOptions += "-StartupTimeout" }
    if ($InvalidUninstallOptions.Count -gt 0) {
        Write-Host ("[!] Režim -Uninstall nepřijímá instalační volby: " + ($InvalidUninstallOptions -join ", ")) -ForegroundColor Red
        exit 64
    }
}

if ($Community.IsPresent -and $NoCommunity.IsPresent) {
    Write-Host "[!] -Community a -NoCommunity nelze použít současně." -ForegroundColor Red
    exit 64
}

$PhysNeMoSpecificOptions = @()
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoDistro)) { $PhysNeMoSpecificOptions += "-PhysNeMoDistro" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoInstallDir)) { $PhysNeMoSpecificOptions += "-PhysNeMoInstallDir" }
if ($null -ne $PhysNeMoNatPort) { $PhysNeMoSpecificOptions += "-PhysNeMoNatPort" }
if (-not [string]::IsNullOrWhiteSpace($NeMoAgentToolkitVersion)) { $PhysNeMoSpecificOptions += "-NeMoAgentToolkitVersion" }
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoVersion)) { $PhysNeMoSpecificOptions += "-PhysicsNeMoVersion" }
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoProfile)) { $PhysNeMoSpecificOptions += "-PhysicsNeMoProfile" }
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoSourceRef)) { $PhysNeMoSpecificOptions += "-PhysicsNeMoSourceRef" }
if ($NoPhysNeMoPrerequisiteInstall.IsPresent) { $PhysNeMoSpecificOptions += "-NoPhysNeMoPrerequisiteInstall" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentBaseUrl)) { $PhysNeMoSpecificOptions += "-PhysNeMoAgentBaseUrl" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentModel)) { $PhysNeMoSpecificOptions += "-PhysNeMoAgentModel" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentApiKeyFile)) { $PhysNeMoSpecificOptions += "-PhysNeMoAgentApiKeyFile" }
if ($NoPhysNeMoAgentAutoDetect.IsPresent) { $PhysNeMoSpecificOptions += "-NoPhysNeMoAgentAutoDetect" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoOpenWebUIUrl)) { $PhysNeMoSpecificOptions += "-PhysNeMoOpenWebUIUrl" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoOpenWebUIApiKeyFile)) { $PhysNeMoSpecificOptions += "-PhysNeMoOpenWebUIApiKeyFile" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoArtifactBaseUrl)) { $PhysNeMoSpecificOptions += "-PhysNeMoArtifactBaseUrl" }
if (-not [string]::IsNullOrWhiteSpace($OpenWebUIDatabase)) { $PhysNeMoSpecificOptions += "-OpenWebUIDatabase" }
if ($NoOpenWebUINativeSync.IsPresent) { $PhysNeMoSpecificOptions += "-NoOpenWebUINativeSync" }
if ($NoOpenWebUIDlpRepair.IsPresent) { $PhysNeMoSpecificOptions += "-NoOpenWebUIDlpRepair" }
if ($AllowPhysNeMoWithoutAgent.IsPresent) { $PhysNeMoSpecificOptions += "-AllowPhysNeMoWithoutAgent" }
if ($NoPhysNeMo.IsPresent -and $PhysNeMoSpecificOptions.Count -gt 0) {
    Write-Host ("[!] -NoPhysNeMo nelze kombinovat s: " + ($PhysNeMoSpecificOptions -join ", ")) -ForegroundColor Red
    exit 64
}
if ($null -ne $PhysNeMoNatPort -and ($PhysNeMoNatPort -lt 1 -or $PhysNeMoNatPort -gt 65535)) {
    Write-Host "[!] -PhysNeMoNatPort musí být v rozsahu 1-65535." -ForegroundColor Red
    exit 64
}
if ($null -ne $PhysNeMoNatPort -and $null -ne $Port -and $PhysNeMoNatPort -eq $Port) {
    Write-Host "[!] Interní PhysicsNeMo NAT port nesmí být shodný s hlavním MCPO portem." -ForegroundColor Red
    exit 64
}
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoProfile) -and $PhysicsNeMoProfile -notin @("base", "cu12", "cu13")) {
    Write-Host "[!] -PhysicsNeMoProfile musí být base, cu12 nebo cu13." -ForegroundColor Red
    exit 64
}
foreach ($VersionValue in @($NeMoAgentToolkitVersion, $PhysicsNeMoVersion)) {
    if (-not [string]::IsNullOrWhiteSpace($VersionValue) -and $VersionValue -notmatch '^[0-9]+(?:\.[0-9]+){1,3}(?:[-+._A-Za-z0-9]*)?$') {
        Write-Host "[!] Neplatný formát verze PhysicsNeMo/NAT: $VersionValue" -ForegroundColor Red
        exit 64
    }
}
foreach ($UrlValue in @($PhysNeMoAgentBaseUrl, $PhysNeMoOpenWebUIUrl, $PhysNeMoArtifactBaseUrl)) {
    if (-not [string]::IsNullOrWhiteSpace($UrlValue)) {
        $uri = $null
        if (-not [System.Uri]::TryCreate($UrlValue, [System.UriKind]::Absolute, [ref]$uri) -or $uri.Scheme -notin @("http", "https")) {
            Write-Host "[!] PhysicsNeMo URL musí být absolutní http:// nebo https:// adresa: $UrlValue" -ForegroundColor Red
            exit 64
        }
    }
}
foreach ($SecretFile in @($PhysNeMoAgentApiKeyFile, $PhysNeMoOpenWebUIApiKeyFile)) {
    if (-not [string]::IsNullOrWhiteSpace($SecretFile) -and -not (Test-Path -LiteralPath $SecretFile -PathType Leaf)) {
        Write-Host "[!] Soubor s PhysicsNeMo/Open WebUI API klíčem nebyl nalezen: $SecretFile" -ForegroundColor Red
        exit 66
    }
}
if (-not [string]::IsNullOrWhiteSpace($OpenWebUIDatabase) -and -not (Test-Path -LiteralPath $OpenWebUIDatabase -PathType Leaf)) {
    Write-Host "[!] Zadaná Open WebUI SQLite databáze nebyla nalezena: $OpenWebUIDatabase" -ForegroundColor Red
    exit 66
}

$WeKnoraSpecificOptions = @()
if (-not [string]::IsNullOrWhiteSpace($WeKnoraUrl)) { $WeKnoraSpecificOptions += "-WeKnoraUrl" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiUrl)) { $WeKnoraSpecificOptions += "-WeKnoraApiUrl" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiKeyFile)) { $WeKnoraSpecificOptions += "-WeKnoraApiKeyFile" }
if ($null -ne $WeKnoraTenantId) { $WeKnoraSpecificOptions += "-WeKnoraTenantId" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraTenantName)) { $WeKnoraSpecificOptions += "-WeKnoraTenantName" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraCaCertificate)) { $WeKnoraSpecificOptions += "-WeKnoraCaCertificate" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraDistro)) { $WeKnoraSpecificOptions += "-WeKnoraDistro" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraInstallDir)) { $WeKnoraSpecificOptions += "-WeKnoraInstallDir" }
if ($NoWeKnoraAutoProvision.IsPresent) { $WeKnoraSpecificOptions += "-NoWeKnoraAutoProvision" }
if ($WeKnoraAllowEmptyCatalog.IsPresent) { $WeKnoraSpecificOptions += "-WeKnoraAllowEmptyCatalog" }
if ($null -ne $WeKnoraHealthTimeout) { $WeKnoraSpecificOptions += "-WeKnoraHealthTimeout" }
if ($NoWeKnora.IsPresent -and $WeKnoraSpecificOptions.Count -gt 0) {
    Write-Host ("[!] -NoWeKnora nelze kombinovat s: " + ($WeKnoraSpecificOptions -join ", ")) -ForegroundColor Red
    exit 64
}

if (($null -ne $WeKnoraTenantId) -and (-not [string]::IsNullOrWhiteSpace($WeKnoraTenantName))) {
    Write-Host "[!] Použijte pouze jednu z voleb -WeKnoraTenantId a -WeKnoraTenantName." -ForegroundColor Red
    exit 64
}
if (($null -ne $WeKnoraTenantId) -and ($WeKnoraTenantId -lt 1)) {
    Write-Host "[!] -WeKnoraTenantId musí být kladné celé číslo." -ForegroundColor Red
    exit 64
}
if (-not [string]::IsNullOrWhiteSpace($WeKnoraTenantName)) {
    $WeKnoraTenantName = $WeKnoraTenantName.Trim()
    if (($WeKnoraTenantName.Length -gt 255) -or $WeKnoraTenantName.Contains("`r") -or $WeKnoraTenantName.Contains("`n")) {
        Write-Host "[!] -WeKnoraTenantName musí být jednořádkový název o délce nejvýše 255 znaků." -ForegroundColor Red
        exit 64
    }
}

function Get-ValidatedWeKnoraUri {
    param(
        [Parameter(Mandatory = $true)][string]$Value,
        [Parameter(Mandatory = $true)][string]$OptionName
    )

    $parsed = $null
    if (-not [System.Uri]::TryCreate($Value, [System.UriKind]::Absolute, [ref]$parsed)) {
        throw "$OptionName musí být platná absolutní URL."
    }
    $scheme = $parsed.Scheme.ToLowerInvariant()
    if ($scheme -notin @("http", "https")) {
        throw "$OptionName musí používat http:// nebo https://."
    }
    if ([string]::IsNullOrWhiteSpace($parsed.Host) -or -not [string]::IsNullOrWhiteSpace($parsed.UserInfo)) {
        throw "$OptionName musí obsahovat host a nesmí obsahovat přihlašovací údaje."
    }
    if (-not [string]::IsNullOrWhiteSpace($parsed.Query) -or -not [string]::IsNullOrWhiteSpace($parsed.Fragment)) {
        throw "$OptionName nesmí obsahovat query string ani fragment."
    }
    return $parsed
}

$parsedWeKnoraUri = $null
$parsedWeKnoraApiUri = $null
try {
if (-not [string]::IsNullOrWhiteSpace($WeKnoraUrl)) {
        $parsedWeKnoraUri = Get-ValidatedWeKnoraUri -Value $WeKnoraUrl -OptionName "-WeKnoraUrl"
    }
    if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiUrl)) {
        $parsedWeKnoraApiUri = Get-ValidatedWeKnoraUri -Value $WeKnoraApiUrl -OptionName "-WeKnoraApiUrl"
    }
}
catch {
    Write-Host "[!] $($_.Exception.Message)" -ForegroundColor Red
    exit 64
}

$effectiveWeKnoraUri = if ($null -ne $parsedWeKnoraApiUri) { $parsedWeKnoraApiUri } else { $parsedWeKnoraUri }
if ($null -ne $effectiveWeKnoraUri) {
    $effectiveScheme = $effectiveWeKnoraUri.Scheme.ToLowerInvariant()
    if ($effectiveScheme -eq "http" -and -not [string]::IsNullOrWhiteSpace($WeKnoraCaCertificate)) {
        Write-Host "[!] -WeKnoraCaCertificate lze použít pouze s efektivní https:// REST URL. Pro http:// parametr certifikátu odeberte." -ForegroundColor Red
        exit 64
    }
    if ($effectiveScheme -eq "http") {
        $loopbackHosts = @("localhost", "127.0.0.1", "::1")
        if ($loopbackHosts -notcontains $effectiveWeKnoraUri.Host.ToLowerInvariant()) {
            Write-Warning "WeKnora REST API je připojeno přes vzdálené http://. API klíč a přenášená data nebudou šifrována; použijte tento režim pouze v důvěryhodné izolované síti."
        }
    }
}

if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiKeyFile)) {
    if (-not (Test-Path -LiteralPath $WeKnoraApiKeyFile -PathType Leaf)) {
        Write-Host "[!] Soubor zadaný přes -WeKnoraApiKeyFile neexistuje: $WeKnoraApiKeyFile" -ForegroundColor Red
        exit 66
    }
    $WeKnoraApiKeyFile = (Resolve-Path -LiteralPath $WeKnoraApiKeyFile).Path
}

if (-not [string]::IsNullOrWhiteSpace($WeKnoraCaCertificate)) {
    if (-not (Test-Path -LiteralPath $WeKnoraCaCertificate -PathType Leaf)) {
        Write-Host "[!] Certifikát zadaný přes -WeKnoraCaCertificate neexistuje: $WeKnoraCaCertificate" -ForegroundColor Red
        exit 66
    }
    $WeKnoraCaCertificate = (Resolve-Path -LiteralPath $WeKnoraCaCertificate).Path
    try {
        $certificateText = [System.IO.File]::ReadAllText($WeKnoraCaCertificate)
        if (-not $certificateText.Contains('-----BEGIN CERTIFICATE-----')) {
            throw 'soubor není PEM certifikát'
        }
    }
    catch {
        Write-Host "[!] -WeKnoraCaCertificate nelze použít: $($_.Exception.Message)" -ForegroundColor Red
        exit 65
    }
}

Write-Host "Engineering MCP Unified Installer $BootstrapperVersion"
Write-Host "MODE=$Mode"
Write-Host "SCRIPT=$EntryScript"

function Test-Python312Command {
    param(
        [Parameter(Mandatory = $true)][string]$Exe,
        [string[]]$Prefix = @()
    )

    try {
        $output = & $Exe @Prefix -c "import sys; print(f'{sys.version_info.major}.{sys.version_info.minor}')" 2>$null
        return ($LASTEXITCODE -eq 0 -and (($output | Select-Object -Last 1).Trim() -eq "3.12"))
    } catch {
        return $false
    }
}

function Find-ExternalPython312 {
    if (Get-Command py -ErrorAction SilentlyContinue) {
        if (Test-Python312Command -Exe "py" -Prefix @("-3.12")) {
            return [pscustomobject]@{ Exe = "py"; Prefix = [string[]]@("-3.12"); Origin = "external" }
        }
    }

    if (Get-Command python3.12 -ErrorAction SilentlyContinue) {
        if (Test-Python312Command -Exe "python3.12") {
            return [pscustomobject]@{ Exe = "python3.12"; Prefix = [string[]]@(); Origin = "external" }
        }
    }

    if (Get-Command python -ErrorAction SilentlyContinue) {
        if (Test-Python312Command -Exe "python") {
            return [pscustomobject]@{ Exe = "python"; Prefix = [string[]]@(); Origin = "external" }
        }
    }

    return $null
}

function Find-InstalledPython312 {
    if ((Test-Path -LiteralPath $InstalledPython) -and (Test-Python312Command -Exe $InstalledPython)) {
        return [pscustomobject]@{ Exe = $InstalledPython; Prefix = [string[]]@(); Origin = "installed" }
    }
    return $null
}


function Find-VenvBasePython312 {
    # A damaged venv can leave Scripts\python.exe behind while pyvenv.cfg is
    # missing or invalid. Never use that redirector to repair itself. If the
    # config is present, try its base interpreter instead.
    $config = Join-Path $InstallHome ".venv\pyvenv.cfg"
    if (-not (Test-Path -LiteralPath $config)) {
        return $null
    }
    try {
        $homeLine = Get-Content -LiteralPath $config -ErrorAction Stop |
            Where-Object { $_ -match '^\s*home\s*=' } |
            Select-Object -First 1
        if (-not $homeLine) { return $null }
        $baseHome = (($homeLine -split '=', 2)[1]).Trim().Trim('"')
        $candidate = Join-Path $baseHome "python.exe"
        if ((Test-Path -LiteralPath $candidate) -and (Test-Python312Command -Exe $candidate)) {
            return [pscustomobject]@{ Exe = $candidate; Prefix = [string[]]@(); Origin = "venv-base" }
        }
    } catch {
        return $null
    }
    return $null
}

function Invoke-PythonBootstrapper {
    param(
        [Parameter(Mandatory = $true)]$Python,
        [Parameter(Mandatory = $true)][string]$Script,
        [Parameter(Mandatory = $true)][string[]]$Arguments
    )

    $pythonExe = [string]$Python.Exe
    $invokeArgs = @($Python.Prefix) + @($Script) + @($Arguments)

    # Windows PowerShell 5.1 převádí stderr nativních programů na ErrorRecord.
    # Při globálním $ErrorActionPreference = "Stop" by i běžná diagnostika
    # Pythonu mohla předčasně ukončit správce. Pro dobu nativního procesu proto
    # používáme Continue, sloučíme oba proudy a následně vrátíme skutečný exit code.
    $previousErrorActionPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = "Continue"
        & $pythonExe @invokeArgs 2>&1 | ForEach-Object {
            # Preserve streaming output without rendering native stderr as a
            # PowerShell NativeCommandError record with misleading line data.
            if ($_ -is [System.Management.Automation.ErrorRecord]) {
                [Console]::Out.WriteLine([string]$_.Exception.Message)
            } else {
                [Console]::Out.WriteLine([string]$_)
            }
        }
        $nativeExitCode = $LASTEXITCODE
        if ($null -eq $nativeExitCode) {
            return 0
        }
        return [int]$nativeExitCode
    } catch {
        Write-Host "[!] Python proces se nepodařilo spustit: $($_.Exception.Message)" -ForegroundColor Red
        return 70
    } finally {
        $ErrorActionPreference = $previousErrorActionPreference
    }
}

function Invoke-NativeCommandQuiet {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [string[]]$ArgumentList = @()
    )

    # Některé nativní nástroje Windows (zejména schtasks.exe) zapisují běžné
    # stavy typu „úloha neexistuje“ na stderr. V PowerShellu 5.1 se při
    # $ErrorActionPreference = "Stop" takový zápis mění na ukončující
    # NativeCommandError. Tato pomocná funkce výstup potlačí a vrátí pouze
    # číselný návratový kód, takže odinstalace zůstává idempotentní.
    $previousErrorActionPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = "SilentlyContinue"
        $captured = & $FilePath @ArgumentList 2>&1
        $nativeExitCode = $LASTEXITCODE
        if ($null -eq $nativeExitCode) {
            return 0
        }
        return [int]$nativeExitCode
    } catch {
        return 9009
    } finally {
        $ErrorActionPreference = $previousErrorActionPreference
    }
}

function Find-UninstallPython {
    # Prefer an interpreter outside APP_HOME.  The installed venv remains a
    # last-resort option because Windows cannot remove loaded .pyd/.dll files
    # until that interpreter has exited.
    $candidates = @()

    if (Get-Command python -ErrorAction SilentlyContinue) {
        $candidates += [pscustomobject]@{ Exe = "python"; Prefix = [string[]]@(); Origin = "external" }
    }
    if (Get-Command python3 -ErrorAction SilentlyContinue) {
        $candidates += [pscustomobject]@{ Exe = "python3"; Prefix = [string[]]@(); Origin = "external" }
    }
    if (Get-Command py -ErrorAction SilentlyContinue) {
        $candidates += [pscustomobject]@{ Exe = "py"; Prefix = [string[]]@(); Origin = "external" }
    }
    if (Test-Path -LiteralPath $InstalledPython) {
        $candidates += [pscustomobject]@{ Exe = $InstalledPython; Prefix = [string[]]@(); Origin = "installed" }
    }

    foreach ($candidate in $candidates) {
        $previousErrorActionPreference = $ErrorActionPreference
        try {
            $ErrorActionPreference = "SilentlyContinue"
            $candidateExe = [string]$candidate.Exe
            $candidateArgs = @($candidate.Prefix) + @("-c", "import sys; print(int(sys.version_info >= (3, 8)))")
            $output = & $candidateExe @candidateArgs 2>&1
            $code = $LASTEXITCODE
            $lastLine = [string](($output | Select-Object -Last 1))
            if (($code -eq 0) -and ($lastLine.Trim() -eq "1")) {
                return $candidate
            }
        } catch {
            # Zkusí se další kandidát, případně čistě PowerShell finalizace.
        } finally {
            $ErrorActionPreference = $previousErrorActionPreference
        }
    }

    return $null
}

function Test-PathInside {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Parent
    )
    try {
        $separator = [System.IO.Path]::DirectorySeparatorChar
        $candidate = [System.IO.Path]::GetFullPath($Path).TrimEnd([char[]]@('\', '/'))
        $root = [System.IO.Path]::GetFullPath($Parent).TrimEnd([char[]]@('\', '/'))
        return (
            [string]::Equals($candidate, $root, [System.StringComparison]::OrdinalIgnoreCase) -or
            $candidate.StartsWith($root + $separator, [System.StringComparison]::OrdinalIgnoreCase)
        )
    } catch {
        return $false
    }
}

function Stop-LegacyUninstallWorkers {
    # Releases 2.5.3 and older created a .cmd worker that waited for the whole
    # interactive PowerShell PID to exit.  A reinstall in the same console could
    # then be deleted later when that console finally closed.  Kill and remove
    # only workers that explicitly reference this exact APP_HOME.
    $found = $false
    $patterns = @("engineering-mcp-uninstall-*.cmd", "engineering-mcp-cleanup-*.cmd")
    $legacyFiles = @()
    foreach ($pattern in $patterns) {
        $legacyFiles += @(Get-ChildItem -LiteralPath $env:TEMP -Filter $pattern -File -ErrorAction SilentlyContinue)
    }

    try {
        $processes = @(Get-CimInstance Win32_Process -Filter "Name='cmd.exe'" -ErrorAction SilentlyContinue)
        foreach ($process in $processes) {
            $commandLine = [string]$process.CommandLine
            $matchesKnownScript = $false
            if ($commandLine) {
                foreach ($file in $legacyFiles) {
                    if (
                        $commandLine.IndexOf($file.FullName, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -or
                        $commandLine.IndexOf($file.Name, [System.StringComparison]::OrdinalIgnoreCase) -ge 0
                    ) {
                        $matchesKnownScript = $true
                        break
                    }
                }
            }
            $matchesHomeWorker = (
                $commandLine -and
                $commandLine.IndexOf($InstallHome, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and
                ($commandLine -match 'engineering-mcp-(uninstall|cleanup)-')
            )
            if ($process.ProcessId -ne $PID -and ($matchesKnownScript -or $matchesHomeWorker)) {
                $found = $true
                Stop-Process -Id ([int]$process.ProcessId) -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {
        # CIM nemusí být dostupné v omezené relaci; soubory se přesto odstraní.
    }

    foreach ($file in $legacyFiles) {
        try {
            $content = Get-Content -LiteralPath $file.FullName -Raw -ErrorAction Stop
            if ($content.IndexOf($InstallHome, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
                $found = $true
                Remove-Item -LiteralPath $file.FullName -Force -ErrorAction SilentlyContinue
            }
        } catch {
            # Nepřístupný cizí cleanup soubor se záměrně nemaže.
        }
    }

    if ($found) {
        Write-Host "[+] Zneškodněn starý odložený cleanup, který mohl později smazat novou instalaci."
    }
    return $found
}

function Get-EngineeringMcpProcesses {
    $result = @()
    try {
        $all = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
        foreach ($process in $all) {
            if ([int]$process.ProcessId -eq $PID) { continue }
            $name = [string]$process.Name
            $executable = [string]$process.ExecutablePath
            $commandLine = [string]$process.CommandLine
            $executableInside = $false
            if ($executable) {
                $executableInside = Test-PathInside -Path $executable -Parent $InstallHome
            }
            $managedName = (
                $name -match '^(python|pythonw|mcpo|uv|uvx)(\.exe)?$' -or
                $name -like '*mcp*.exe'
            )
            $commandReferencesHome = (
                $commandLine -and
                $commandLine.IndexOf($InstallHome, [System.StringComparison]::OrdinalIgnoreCase) -ge 0
            )
            if ($executableInside -or ($managedName -and $commandReferencesHome)) {
                $result += $process
            }
        }
    } catch {
        # PID soubory a Remove-Item retry zůstávají dostupné i bez CIM.
    }
    return @($result)
}

function Stop-EngineeringMcpProcesses {
    foreach ($pidFileName in @("supervisor.pid", "mcpo.pid")) {
        $pidFile = Join-Path $InstallHome $pidFileName
        if (Test-Path -LiteralPath $pidFile) {
            try {
                $processId = [int](Get-Content -LiteralPath $pidFile -Raw).Trim()
                $taskkill = Get-Command taskkill.exe -ErrorAction SilentlyContinue
                if ($null -ne $taskkill) {
                    $taskkillPath = if ($taskkill.Source) { [string]$taskkill.Source } else { "taskkill.exe" }
                    [void](Invoke-NativeCommandQuiet -FilePath $taskkillPath -ArgumentList @("/PID", "$processId", "/T", "/F"))
                }
                Stop-Process -Id $processId -Force -ErrorAction SilentlyContinue
            } catch {
                # Proces už pravděpodobně neběží.
            }
        }
    }

    for ($attempt = 1; $attempt -le 6; $attempt++) {
        $managed = @(Get-EngineeringMcpProcesses)
        if ($managed.Count -eq 0) { break }
        foreach ($process in $managed) {
            $processId = [int]$process.ProcessId
            $taskkill = Get-Command taskkill.exe -ErrorAction SilentlyContinue
            if ($null -ne $taskkill) {
                $taskkillPath = if ($taskkill.Source) { [string]$taskkill.Source } else { "taskkill.exe" }
                [void](Invoke-NativeCommandQuiet -FilePath $taskkillPath -ArgumentList @("/PID", "$processId", "/T", "/F"))
            }
            Stop-Process -Id $processId -Force -ErrorAction SilentlyContinue
        }
        Start-Sleep -Milliseconds 500
    }
}

function Remove-DirectoryWithRetry {
    param(
        [Parameter(Mandatory = $true)][string]$Target,
        [int]$Attempts = 15
    )
    if (-not (Test-Path -LiteralPath $Target)) { return $true }

    for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
        try {
            [GC]::Collect()
            [GC]::WaitForPendingFinalizers()
            Remove-Item -LiteralPath $Target -Recurse -Force -ErrorAction Stop
        } catch {
            # cmd/rmdir sometimes succeeds where the PowerShell provider keeps a
            # transient enumeration handle.  Its exit code is not trusted; the
            # path existence check below is authoritative.
            $cmd = Get-Command cmd.exe -ErrorAction SilentlyContinue
            if ($null -ne $cmd) {
                $cmdPath = if ($cmd.Source) { [string]$cmd.Source } else { "cmd.exe" }
                $escaped = $Target.Replace('"', '""')
                [void](Invoke-NativeCommandQuiet -FilePath $cmdPath -ArgumentList @("/d", "/s", "/c", ('rmdir /s /q "' + $escaped + '"')))
            }
        }
        if (-not (Test-Path -LiteralPath $Target)) { return $true }
        Start-Sleep -Milliseconds ([Math]::Min(1200, 200 + (100 * $attempt)))
    }
    return (-not (Test-Path -LiteralPath $Target))
}

function Write-PendingCleanupMarker {
    param([Parameter(Mandatory = $true)][string]$Target)
    try {
        $payload = [ordered]@{
            schema = 1
            bootstrapper_version = $BootstrapperVersion
            original = $InstallHome
            target = $Target
            created_at = (Get-Date).ToString("o")
        }
        $payload | ConvertTo-Json | Set-Content -LiteralPath $PendingCleanupMarker -Encoding UTF8
    } catch {
        Write-Warning "Nelze zapsat cleanup marker: $($_.Exception.Message)"
    }
}

function Start-DirectoryCleanupWorker {
    param([Parameter(Mandatory = $true)][string]$Target)
    try {
        $cleanup = Join-Path $env:TEMP ("engineering-mcp-cleanup-v254-" + [guid]::NewGuid().ToString("N") + ".cmd")
        $escapedTarget = $Target.Replace('%', '%%').Replace('"', '""')
        @"
@echo off
setlocal
set "TARGET=$escapedTarget"
for /L %%I in (1,1,300) do (
  if not exist "%TARGET%" goto cleaned
  rmdir /s /q "%TARGET%" >nul 2>&1
  if not exist "%TARGET%" goto cleaned
  timeout /t 1 /nobreak >nul
)
goto finished
:cleaned
:finished
del /f /q "%~f0" >nul 2>&1
"@ | Set-Content -LiteralPath $cleanup -Encoding ASCII
        Start-Process -FilePath $env:ComSpec -ArgumentList @("/d", "/s", "/c", ('"' + $cleanup + '"')) -WindowStyle Hidden -ErrorAction Stop | Out-Null
        return $true
    } catch {
        Write-Warning "Odložený cleanup nelze spustit: $($_.Exception.Message)"
        return $false
    }
}

function Move-InstallHomeToTombstone {
    if (-not (Test-Path -LiteralPath $InstallHome)) { return $null }
    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $target = Join-Path $InstallParent ($InstallLeaf + ".uninstalling." + $timestamp + "." + [guid]::NewGuid().ToString("N"))
    try {
        [System.IO.Directory]::Move($InstallHome, $target)
        return $target
    } catch {
        return $null
    }
}

function Complete-PendingUninstallCleanup {
    # Remove stale tombstones and a v2.5.4 pending target before a new operation.
    # A marker that still points at APP_HOME means the previous uninstall did
    # not reach a safe state, so installation is blocked until cleanup succeeds.
    $legacyCleanupFound = Stop-LegacyUninstallWorkers
    if ($legacyCleanupFound) {
        Stop-EngineeringMcpProcesses
    }

    $targets = @()
    $markerTarget = $null
    if (Test-Path -LiteralPath $PendingCleanupMarker) {
        try {
            $marker = Get-Content -LiteralPath $PendingCleanupMarker -Raw | ConvertFrom-Json
            $markerTarget = [string]$marker.target
            if ($markerTarget) { $targets += $markerTarget }
        } catch {
            Remove-Item -LiteralPath $PendingCleanupMarker -Force -ErrorAction SilentlyContinue
        }
    }
    $targets += @(
        Get-ChildItem -LiteralPath $InstallParent -Directory -Filter ($InstallLeaf + ".uninstalling.*") -ErrorAction SilentlyContinue |
            ForEach-Object { $_.FullName }
    )

    foreach ($target in @($targets | Select-Object -Unique)) {
        if (-not $target) { continue }
        if ([string]::Equals($target, $InstallHome, [System.StringComparison]::OrdinalIgnoreCase)) {
            Stop-EngineeringMcpProcesses
            if (-not (Remove-DirectoryWithRetry -Target $InstallHome -Attempts 20)) {
                $tombstone = Move-InstallHomeToTombstone
                if ($null -eq $tombstone) {
                    Write-Host "[!] Předchozí odinstalace stále drží zamčený adresář: $InstallHome" -ForegroundColor Red
                    Write-Host "    Zavřete proces, který jej používá, nebo restartujte Windows a spusťte stejný příkaz znovu."
                    return $false
                }
                $target = $tombstone
            }
        }
        if (Test-Path -LiteralPath $target) {
            if (-not (Remove-DirectoryWithRetry -Target $target -Attempts 8)) {
                Write-PendingCleanupMarker -Target $target
                $markerTarget = $target
                [void](Start-DirectoryCleanupWorker -Target $target)
            }
        }
    }

    if ($markerTarget -and [string]::Equals($markerTarget, $InstallHome, [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $InstallHome)) {
        return $false
    }
    if (-not $markerTarget -or -not (Test-Path -LiteralPath $markerTarget -ErrorAction SilentlyContinue)) {
        Remove-Item -LiteralPath $PendingCleanupMarker -Force -ErrorAction SilentlyContinue
    }
    return $true
}

function Invoke-PowerShellUninstallFinalizer {
    Write-Host "[*] Dokončuji odinstalaci po ukončení Python procesu."
    $resultCode = 0
    [void](Stop-LegacyUninstallWorkers)

    $schtasksCommand = Get-Command schtasks.exe -ErrorAction SilentlyContinue
    if ($null -ne $schtasksCommand) {
        $schtasksPath = if ($schtasksCommand.Source) { [string]$schtasksCommand.Source } else { "schtasks.exe" }
        $queryCode = Invoke-NativeCommandQuiet -FilePath $schtasksPath -ArgumentList @("/Query", "/TN", $TaskName)
        if ($queryCode -eq 0) {
            [void](Invoke-NativeCommandQuiet -FilePath $schtasksPath -ArgumentList @("/End", "/TN", $TaskName))
            $deleteCode = Invoke-NativeCommandQuiet -FilePath $schtasksPath -ArgumentList @("/Delete", "/TN", $TaskName, "/F")
            if ($deleteCode -eq 0) {
                Write-Host "[+] Naplánovaná úloha '$TaskName' byla odstraněna."
            } else {
                Write-Warning "Naplánovanou úlohu '$TaskName' se nepodařilo odstranit (kód $deleteCode)."
                $resultCode = 1
            }
        } else {
            Write-Host "[*] Naplánovaná úloha '$TaskName' není registrována; není co odstraňovat."
        }
    }

    Stop-EngineeringMcpProcesses

    try {
        $currentLocation = (Get-Location).Path
        if (Test-PathInside -Path $currentLocation -Parent $InstallHome) {
            Set-Location -LiteralPath $env:TEMP
        }
    } catch {
        # Remove/rename will provide the authoritative result.
    }

    if (-not (Test-Path -LiteralPath $InstallHome)) {
        Remove-Item -LiteralPath $PendingCleanupMarker -Force -ErrorAction SilentlyContinue
        Write-Host "[+] Engineering MCP již není nainstalováno: $InstallHome"
        return $resultCode
    }

    if (Remove-DirectoryWithRetry -Target $InstallHome -Attempts 20) {
        Remove-Item -LiteralPath $PendingCleanupMarker -Force -ErrorAction SilentlyContinue
        Write-Host "[+] Odstraněno: $InstallHome"
        return $resultCode
    }

    # Renaming frees the canonical path immediately, so a subsequent -Install
    # cannot inherit the old checkpoint and a background cleanup can safely work
    # on a uniquely named tombstone without ever touching a new installation.
    $tombstone = Move-InstallHomeToTombstone
    if ($null -ne $tombstone) {
        Write-Host "[+] Starý adresář byl bezpečně odstaven: $tombstone"
        if (-not (Remove-DirectoryWithRetry -Target $tombstone -Attempts 8)) {
            Write-PendingCleanupMarker -Target $tombstone
            [void](Start-DirectoryCleanupWorker -Target $tombstone)
            Write-Host "[*] Zbylé zamčené soubory budou odstraněny na pozadí; nová instalace již může použít $InstallHome."
        } else {
            Remove-Item -LiteralPath $PendingCleanupMarker -Force -ErrorAction SilentlyContinue
        }
        return $resultCode
    }

    # Do not claim success while the original canonical path still exists.  The
    # worker no longer waits for this PowerShell PID, but Install/Resume will
    # also inspect the marker and refuse to reuse the half-uninstalled tree.
    Write-PendingCleanupMarker -Target $InstallHome
    [void](Start-DirectoryCleanupWorker -Target $InstallHome)
    Write-Host "[!] Adresář je stále zamčený a nebylo jej možné ani přejmenovat: $InstallHome" -ForegroundColor Red
    Write-Host "    Odinstalace bude pokračovat na pozadí. Do odstranění adresáře se nová instalace nespustí."
    return 1
}

function Deploy-SinglePowerShellEntryPoint {
    if (-not (Test-Path -LiteralPath $InstallHome)) {
        return
    }

    $sourceFull = [System.IO.Path]::GetFullPath($EntryScript)
    $targetFull = [System.IO.Path]::GetFullPath($InstalledEntryScript)
    if (-not [string]::Equals($sourceFull, $targetFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        Copy-Item -LiteralPath $EntryScript -Destination $InstalledEntryScript -Force
    }

    # Odstranění starých rozdělených wrapperů. Autoritativní PowerShell
    # vstupní bod je pouze install-engineering-mcp-unified-v2.9.18.ps1; aktuální soubor se nikdy nemaže.
    foreach ($staleName in @(
        "install.ps1",
        "install-engineering-mcp-complete-suite-v2.7.0.ps1",
        "install-engineering-mcp-physnemo-v1.0.0.ps1",
        "install-engineering-mcp-physnemo-v1.0.1-wsl-transport-fix.ps1",
        "install-engineering-mcp-unified-v2.8.0.ps1",
        "install-engineering-mcp-unified-v2.8.1.ps1",
        "install-engineering-mcp-unified-v2.8.2.ps1",
        "install-engineering-mcp-unified-v2.8.3.ps1",
        "install-engineering-mcp-unified-v2.8.4.ps1",
        "install-engineering-mcp-unified-v2.8.5.ps1",
        "install-engineering-mcp-unified-v2.8.6.ps1",
        "install-engineering-mcp-unified-v2.8.7.ps1",
        "install-engineering-mcp-unified-v2.8.8.ps1",
        "install-engineering-mcp-unified-v2.9.0.ps1",
        "install-engineering-mcp-unified-v2.9.1.ps1",
        "install-engineering-mcp-unified-v2.9.2.ps1",
        "install-engineering-mcp-unified-v2.9.3.ps1",
        "install-engineering-mcp-unified-v2.9.4.ps1",
        "install-engineering-mcp-unified-v2.9.5.ps1",
        "install-engineering-mcp-unified-v2.9.6.ps1",
        "install-engineering-mcp-unified-v2.9.7.ps1",
        "install-engineering-mcp-unified-v2.9.8.ps1",
        "install-engineering-mcp-unified-v2.9.9.ps1",
        "install-engineering-mcp-unified-v2.9.10.ps1",
        "install-engineering-mcp-unified-v2.9.11.ps1",
        "install-engineering-mcp-unified-v2.9.12.ps1",
        "install-engineering-mcp-weknora-v2.6.2-http-https.ps1",
        "install-engineering-mcp-weknora-v2.6.3-openapi-fix.ps1",
        "install-engineering-mcp-weknora-v2.6.4-kb-catalog-fix.ps1",
        "uninstall.ps1",
        "resume.ps1",
        "uninstall-engineering-mcp.cmd",
        "resume-engineering-mcp.cmd",
        "uninstall-engineering-mcp.sh",
        "resume-engineering-mcp.sh",
        "install-engineering-mcp-unified-v2.9.14.ps1"
    )) {
        $stalePath = Join-Path $InstallHome $staleName
        Remove-Item -LiteralPath $stalePath -Force -ErrorAction SilentlyContinue
    }
}

Expand-EmbeddedBootstrap
Assert-EngineeringBootstrapSource -Path $SourceScript

switch ($Mode) {
    "UNINSTALL" {
        # Tato větev je úplně oddělená. Neobsahuje winget, pip, --install ani
        # --resume a vždy končí explicitním exit.
        $python = Find-UninstallPython

        $script = if (Test-Path -LiteralPath $SourceScript) {
            $SourceScript
        } elseif (Test-Path -LiteralPath $InstalledScript) {
            $InstalledScript
        } else {
            $null
        }

        if (($null -ne $python) -and ($null -ne $script)) {
            Write-Host "[*] Spouštím Python režim=UNINSTALL"
            $code = Invoke-PythonBootstrapper -Python $python -Script $script -Arguments @("--uninstall")
            if ($code -ne 0) {
                Write-Warning "Python odinstalátor skončil kódem $code; finální PowerShell cleanup přesto pokračuje."
            }
        } else {
            Write-Host "[*] Použitelný Python nebo Python správce nebyl nalezen; pokračuji PowerShell finalizací."
        }

        # Always finalize after the Python process has exited.  This is the only
        # safe point to remove the venv and its loaded native extension DLLs.
        $finalizerCode = Invoke-PowerShellUninstallFinalizer
        Remove-EmbeddedBootstrap
        exit $finalizerCode
    }

    "INSTALL" {
        $PythonOperation = "--install"
    }

    "RESUME" {
        $PythonOperation = "--resume"
    }

    default {
        Write-Host "[!] Interní chyba: neznámý režim $Mode." -ForegroundColor Red
        exit 70
    }
}

# Od tohoto místa je možný pouze INSTALL nebo RESUME.
if (-not (Complete-PendingUninstallCleanup)) {
    Write-Host "[!] Nelze pokračovat, dokud není dokončena předchozí odinstalace." -ForegroundColor Red
    exit 75
}

$VenvPython = Join-Path $InstallHome ".venv\Scripts\python.exe"
$VenvConfig = Join-Path $InstallHome ".venv\pyvenv.cfg"
if (($Mode -eq "RESUME") -and (Test-Path -LiteralPath $VenvPython) -and (-not (Test-Path -LiteralPath $VenvConfig))) {
    Write-Warning "Nalezena neúplná .venv: python.exe existuje, ale pyvenv.cfg chybí. Verze 2.9.18 prostředí automaticky přestaví."
}
# Oprava je součástí standardního instalačního toku. Nový bootstrap je již
# opravený; tato migrace navíc bezpečně opraví i starou 2.5.4 kopii, pokud byla
# ponechána v instalačním adresáři.
Assert-EngineeringBootstrapSource -Path $SourceScript
if (Test-Path -LiteralPath $InstalledScript) {
    # The current embedded source is authoritative.  An existing deployed copy
    # is validated after the Python bootstrap has refreshed it.
    Write-Host "[*] Existující jednotný Python bootstrap bude ověřen/aktualizován v režimu $Mode."
}

$python = Find-ExternalPython312
if (($null -eq $python) -and ($Mode -eq "RESUME")) {
    $python = Find-VenvBasePython312
}
if (($null -eq $python) -and ($Mode -eq "RESUME")) {
    $python = Find-InstalledPython312
}

if ($null -eq $python) {
    if (Get-Command winget -ErrorAction SilentlyContinue) {
        Write-Host "[*] Instaluji Python 3.12 pomocí winget..."
        & winget install --id Python.Python.3.12 -e --accept-source-agreements --accept-package-agreements
        if ($LASTEXITCODE -ne 0) {
            $wingetExitCode = $LASTEXITCODE
            Write-Host "[!] winget nedokázal nainstalovat Python 3.12 (kód $wingetExitCode)." -ForegroundColor Red
            exit $wingetExitCode
        }
        $python = Find-ExternalPython312
    }
}

if ($null -eq $python) {
    Write-Host "[!] Python 3.12 nebyl nalezen. Nainstalujte jej a spusťte stejný režim znovu." -ForegroundColor Red
    exit 69
}

Write-Host "[*] Bootstrap Python: $($python.Exe) (origin=$($python.Origin))"
$bootstrapArgs = @($PythonOperation)
if ($null -ne $Port) { $bootstrapArgs += @("--port", "$Port") }
if ($null -ne $StartupTimeout) { $bootstrapArgs += @("--startup-timeout", "$StartupTimeout") }
if ($null -ne $MatlabHealthTimeout) { $bootstrapArgs += @("--matlab-health-timeout", "$MatlabHealthTimeout") }
if ($NoPhysNeMo.IsPresent) { $bootstrapArgs += "--no-physnemo" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoDistro)) { $bootstrapArgs += @("--physnemo-distro", $PhysNeMoDistro) }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoInstallDir)) { $bootstrapArgs += @("--physnemo-install-dir", $PhysNeMoInstallDir) }
if ($null -ne $PhysNeMoNatPort) { $bootstrapArgs += @("--physnemo-nat-port", "$PhysNeMoNatPort") }
if (-not [string]::IsNullOrWhiteSpace($NeMoAgentToolkitVersion)) { $bootstrapArgs += @("--physnemo-nat-version", $NeMoAgentToolkitVersion) }
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoVersion)) { $bootstrapArgs += @("--physicsnemo-version", $PhysicsNeMoVersion) }
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoProfile)) { $bootstrapArgs += @("--physicsnemo-profile", $PhysicsNeMoProfile) }
if (-not [string]::IsNullOrWhiteSpace($PhysicsNeMoSourceRef)) { $bootstrapArgs += @("--physicsnemo-source-ref", $PhysicsNeMoSourceRef) }
if ($NoPhysNeMoPrerequisiteInstall.IsPresent) { $bootstrapArgs += "--no-physnemo-install-prerequisites" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentBaseUrl)) { $bootstrapArgs += @("--physnemo-agent-base-url", $PhysNeMoAgentBaseUrl) }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentModel)) { $bootstrapArgs += @("--physnemo-agent-model", $PhysNeMoAgentModel) }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoAgentApiKeyFile)) { $bootstrapArgs += @("--physnemo-agent-api-key-file", $PhysNeMoAgentApiKeyFile) }
if ($NoPhysNeMoAgentAutoDetect.IsPresent) { $bootstrapArgs += "--no-physnemo-agent-auto-detect" }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoOpenWebUIUrl)) { $bootstrapArgs += @("--physnemo-openwebui-url", $PhysNeMoOpenWebUIUrl) }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoOpenWebUIApiKeyFile)) { $bootstrapArgs += @("--physnemo-openwebui-api-key-file", $PhysNeMoOpenWebUIApiKeyFile) }
if (-not [string]::IsNullOrWhiteSpace($PhysNeMoArtifactBaseUrl)) { $bootstrapArgs += @("--physnemo-artifact-base-url", $PhysNeMoArtifactBaseUrl) }
if (-not [string]::IsNullOrWhiteSpace($OpenWebUIDatabase)) { $bootstrapArgs += @("--openwebui-database", $OpenWebUIDatabase) }
if ($NoOpenWebUINativeSync.IsPresent) { $bootstrapArgs += "--no-openwebui-native-sync" }
if ($NoOpenWebUIDlpRepair.IsPresent) { $bootstrapArgs += "--no-openwebui-dlp-repair" }
if ($AllowPhysNeMoWithoutAgent.IsPresent) { $bootstrapArgs += "--physnemo-allow-unconfigured-agent" }
if ($NoWeKnora.IsPresent) { $bootstrapArgs += "--no-weknora" }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraUrl)) { $bootstrapArgs += @("--weknora-url", $WeKnoraUrl) }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiUrl)) { $bootstrapArgs += @("--weknora-api-url", $WeKnoraApiUrl) }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiKeyFile)) { $bootstrapArgs += @("--weknora-api-key-file", $WeKnoraApiKeyFile) }
if ($null -ne $WeKnoraTenantId) { $bootstrapArgs += @("--weknora-tenant-id", "$WeKnoraTenantId") }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraTenantName)) { $bootstrapArgs += @("--weknora-tenant-name", $WeKnoraTenantName) }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraCaCertificate)) { $bootstrapArgs += @("--weknora-ca-certificate", $WeKnoraCaCertificate) }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraDistro)) { $bootstrapArgs += @("--weknora-distro", $WeKnoraDistro) }
if (-not [string]::IsNullOrWhiteSpace($WeKnoraInstallDir)) { $bootstrapArgs += @("--weknora-install-dir", $WeKnoraInstallDir) }
if ($NoWeKnoraAutoProvision.IsPresent) { $bootstrapArgs += "--no-weknora-auto-provision" }
if ($WeKnoraAllowEmptyCatalog.IsPresent) { $bootstrapArgs += "--weknora-allow-empty-catalog" }
if ($null -ne $WeKnoraHealthTimeout) { $bootstrapArgs += @("--weknora-health-timeout", "$WeKnoraHealthTimeout") }
if ($NoMatlabRepair.IsPresent) { $bootstrapArgs += "--no-matlab-repair" }
if ($ForceCloseMatlab.IsPresent) {
    Write-Warning "-ForceCloseMatlab může ukončit MATLAB a zahodit neuloženou práci."
    $bootstrapArgs += "--matlab-force-close"
}
if ($Community.IsPresent) { $bootstrapArgs += "--community" }
if ($NoCommunity.IsPresent) { $bootstrapArgs += "--no-community" }
if ($NoStart.IsPresent) { $bootstrapArgs += "--no-run-after-install" }
if ($NoAutostart.IsPresent) { $bootstrapArgs += "--no-autostart" }
if ($Force.IsPresent) { $bootstrapArgs += "--force" }

Write-Host "[*] Spouštím Python režim=$Mode"
$code = Invoke-PythonBootstrapper -Python $python -Script $SourceScript -Arguments $bootstrapArgs
if ($code -ne 0) {
    Write-Host "[!] Engineering MCP Unified Bootstrapper skončil kódem $code." -ForegroundColor Red
    Remove-EmbeddedBootstrap
    exit $code
}

Deploy-SinglePowerShellEntryPoint
Write-Host "[+] Jediný PowerShell správce byl uložen do: $InstalledEntryScript"

if (Test-Path -LiteralPath $InstalledScript) {
    Assert-EngineeringBootstrapSource -Path $InstalledScript
}

if ($MatlabImageTest.IsPresent) {
    $testPython = Find-InstalledPython312
    $testScript = $InstalledScript
    if (($null -eq $testPython) -or (-not (Test-Path -LiteralPath $testScript))) {
        $testPython = $python
        $testScript = $SourceScript
    }
    $testArgs = @("--matlab-image-test")
    if ($null -ne $StartupTimeout) {
        $testArgs += @("--startup-timeout", "$StartupTimeout")
    }
    Write-Host "[*] Spouštím přímý MATLAB image test bez jazykového modelu."
    $testCode = Invoke-PythonBootstrapper -Python $testPython -Script $testScript -Arguments $testArgs
    if ($testCode -ne 0) {
        Write-Host "[!] MATLAB image test skončil kódem $testCode." -ForegroundColor Red
        Remove-EmbeddedBootstrap
        exit $testCode
    }
}

Write-Host "[+] Další operace:"
if (-not $NoPhysNeMo.IsPresent) {
    Write-Host "    PhysicsNeMo: integrovaná route v hlavním MCPO gateway"
    if (-not [string]::IsNullOrWhiteSpace($PhysNeMoDistro)) { Write-Host "    PhysicsNeMo WSL2: $PhysNeMoDistro" }
    if ($null -ne $PhysNeMoNatPort) { Write-Host "    PhysicsNeMo interní NAT MCP port: $PhysNeMoNatPort" }
}
if (-not [string]::IsNullOrWhiteSpace($WeKnoraUrl)) {
    Write-Host "    WeKnora veřejný/webový cíl: $WeKnoraUrl"
}
if (-not [string]::IsNullOrWhiteSpace($WeKnoraApiUrl)) {
    Write-Host "    WeKnora explicitní REST API cíl: $WeKnoraApiUrl"
}
if ($null -ne $WeKnoraTenantId) {
    Write-Host "    WeKnora cílový workspace tenant_id: $WeKnoraTenantId"
}
if (-not [string]::IsNullOrWhiteSpace($WeKnoraTenantName)) {
    Write-Host "    WeKnora cílový workspace: $WeKnoraTenantName"
}
if (-not [string]::IsNullOrWhiteSpace($WeKnoraCaCertificate)) {
    Write-Host "    WeKnora privátní CA: $WeKnoraCaCertificate"
}
Write-Host "    & `"$InstalledEntryScript`" -Resume"
Write-Host "    & `"$InstalledEntryScript`" -Uninstall"
Remove-EmbeddedBootstrap
exit 0
